namespace ghidra.trace.util;

using generic.util;
using ghidra.trace.model;
using ghidra.trace.model.Lifespan;
using ghidra.trace.model.Lifespan;
using ghidra.trace.model;
using ghidra.trace.model.time;
using ghidra.trace.model.time;
using ghidra.trace.model.time.schedule;

public class TraceViewportSpanIterator : AbstractPeekableIterator<Lifespan> {
	private TraceTimeManager timeManager;
	private MutableLifeSet set = new DefaultLifeSet();
	private long snap;
	private bool done = false;

	public TraceViewportSpanIterator(Trace trace, long snap) {
		this.timeManager = trace.getTimeManager();
		this.snap = snap;
	}

	protected TraceSnapshot locateMostRecentFork(long from) {
		while (true) {
			TraceSnapshot prev = timeManager.getMostRecentSnapshot(from);
			if (prev == null) {
				return null;
			}
			TraceSchedule prevSched = prev.getSchedule();
			long prevKey = prev.getKey();
			if (prevSched == null) {
				if (prevKey == long.MinValue) {
					return null;
				}
				from = prevKey - 1;
				continue;
			}
			long forkedSnap = prevSched.getSnap();
			if (forkedSnap == prevKey - 1) {
				// Schedule is notational without forking
				from--;
				continue;
			}
			return prev;
		}
	}

	/* @Override */
	protected Lifespan seekNext() {
		if (done) {
			return null;
		}
		long curSnap = snap;
		TraceSnapshot fork = locateMostRecentFork(snap);
		long prevSnap = fork == null ? long.MinValue : fork.getKey();
		if (fork == null) {
			done = true;
		}
		else if (set.contains(prevSnap)) {
			done = true;
			return null;
		}
		else {
			snap = fork.getSchedule().getSnap();
		}
		Lifespan range = Lifespan.span(prevSnap, curSnap);
		set.add(range);
		return range;
	}
}
